	CONFIG "MS_ERRORFILE" "/srv/mapserver/err_tuberia_agua_condominios.log"
	DEBUG 0
	LAYER
        PROJECTION
		 'init=epsg:32614'
		END #PROJECTION
		CONNECTIONTYPE POSTGIS
		NAME "SS_MAP_COND_TUBERIA_INFO"
		STATUS DEFAULT
		INCLUDE 'includes/conexion.map'
		DATA "geometry from (select ts.gid, ts.diametro as diametro, ts.geometry as geometry from tuberiassec ts WHERE ts.cl_responsable_mantenimiento=2) as tmp using unique gid using srid=32614"
		TYPE line
		MINSCALE 1
		MAXSCALE 35000
		LABELITEM "diametro"
		CLASS
			NAME "Tuberia Agua"
			LABEL
				TYPE TRUETYPE
				FONT "arial"
				SIZE 19
				COLOR 0 0 255
			END #LABEL
		END #CLASS
	END #LAYER
